cd /luxon && cat > tmp_fuzz.js <<'EOF'
import { Duration } from "./src/luxon";
const units = ["years","quarters","months","weeks","days","hours","minutes","seconds","milliseconds"];
// ms per unit (casual)
const ms = {};
for (const u of units) ms[u] = Duration.fromObject({[u]:1}).as("milliseconds");
const total = o => Object.keys(o).reduce((a,k)=>a+o[k]*ms[k],0);
let bad = 0, checked = 0;
const rnd = (()=>{let s=12345;return()=>{s=(s*1103515245+12345)%2147483648;return s/2147483648;};})();
for (let iter=0; iter<20000; iter++) {
  const n = 1 + Math.floor(rnd()*4);
  const obj = {};
  for (let i=0;i<n;i++) {
    const u = units[Math.floor(rnd()*units.length)];
    const v = Math.round((rnd()*200-100)*1000)/1000;
    obj[u] = (obj[u]||0) + v;
  }
  const dur = Duration.fromObject(obj);
  const norm = dur.normalize();
  checked++;
  const t1 = total(obj), t2 = total(norm.toObject());
  if (Math.abs(t1-t2) > 1e-6*Math.max(1,Math.abs(t1))) { bad++; if(bad<10) console.log("VALUE CHANGE", JSON.stringify(obj), "->", JSON.stringify(norm.toObject()), t1, t2); }
  // idempotence
  const norm2 = norm.normalize().toObject();
  if (JSON.stringify(norm2) !== JSON.stringify(norm.toObject())) { bad++; if(bad<10) console.log("NOT IDEMPOTENT", JSON.stringify(norm.toObject()), "->", JSON.stringify(norm2)); }
  // shiftTo each single unit agrees with as()
  for (const u of units) {
    const a = dur.as(u), s = dur.shiftTo(u).get(u);
    if (!(Math.abs(a-s) <= 1e-9*Math.max(1,Math.abs(a)))) { bad++; if(bad<10) console.log("as/shiftTo mismatch", JSON.stringify(obj), u, a, s); }
    if (!(Math.abs(a*ms[u]-t1) <= 1e-6*Math.max(1,Math.abs(t1)))) { bad++; if(bad<10) console.log("as total mismatch", JSON.stringify(obj), u, a*ms[u], t1); }
  }
  // shiftTo all units should equal normalize
  const all = dur.shiftTo(...units).toObject();
  if (JSON.stringify(all) !== JSON.stringify(norm.toObject())) { bad++; if(bad<10) console.log("shiftToAll != normalize", JSON.stringify(obj), JSON.stringify(all), JSON.stringify(norm.toObject())); }
}
console.log("checked", checked, "bad", bad);
EOF
