import { DateTime } from "./src/luxon";

const zones = ["America/New_York", "America/Los_Angeles", "America/Chicago", "America/Denver",
  "Europe/London", "Europe/Paris", "Australia/Sydney", "Australia/Adelaide", "Pacific/Auckland",
  "Asia/Kolkata", "Africa/Cairo", "America/Sao_Paulo", "Asia/Tehran", "UTC"];
const years = [1942, 1943, 1945, 1974, 1975, 1982, 2018, 2019, 2020];

let mismatches = [];
let checked = 0;
for (const zone of zones) {
  for (const year of years) {
    // reference: minimum offset observed in the local year (standard time)
    let min = Infinity;
    for (let d = DateTime.fromObject({ year, month: 1, day: 1, hour: 12 }, { zone }); d.year === year; d = d.plus({ days: 1 })) {
      min = Math.min(min, d.offset);
    }
    if (min === Infinity) continue;
    for (let d = DateTime.fromObject({ year, month: 1, day: 1, hour: 12 }, { zone }); d.year === year; d = d.plus({ days: 1 })) {
      checked++;
      const expected = d.offset > min;
