        mismatches.push(`${zone} ${d.toISODate()} offset=${d.offset} min=${min} isInDST=${d.isInDST} expected=${expected}`);
      }
    }
  }
}
console.log("checked", checked, "mismatches", mismatches.length);
console.log(mismatches.slice(0, 15).join("\n"));
